(function($){'use strict';const GHLWizard={currentStep:1,totalSteps:6,settings:{},init:function(){if(syncly_setup_wizard_js_data.settings){this.settings={enable_user_sync:syncly_setup_wizard_js_data.settings.enable_user_sync,user_register:syncly_setup_wizard_js_data.settings.user_register,user_register_tags:syncly_setup_wizard_js_data.settings.user_register_tags||[],woocommerce:syncly_setup_wizard_js_data.settings.woocommerce,buddyboss:syncly_setup_wizard_js_data.settings.buddyboss,learndash:syncly_setup_wizard_js_data.settings.learndash,delete_contact_on_user_delete:syncly_setup_wizard_js_data.settings.delete_contact_on_user_delete,enable_sync_logging:syncly_setup_wizard_js_data.settings.enable_sync_logging,enable_telemetry_reporting:syncly_setup_wizard_js_data.settings.enable_telemetry_reporting}}
this.initTagsSelect2();this.bindEvents();this.updateStepIndicators()},initTagsSelect2:function(){const $tagsSelect=$('#wizard_user_register_tags');const $userRegisterCheckbox=$('#wizard_user_register');const $tagsSection=$('#wizard_user_register_tags_section');if($tagsSelect.length===0){return}
$userRegisterCheckbox.on('change',function(){if($(this).is(':checked')){$tagsSection.slideDown(300);if($tagsSelect.find('option').length<=1){GHLWizard.loadTags()}}else{$tagsSection.slideUp(300)}});if($userRegisterCheckbox.is(':checked')){this.loadTags()}},loadTags:function(){const $tagsSelect=$('#wizard_user_register_tags');const savedTags=syncly_setup_wizard_js_data.settings.user_register_tags||[];var tags=syncly_setup_wizard_js_data.tags||[];$tagsSelect.empty();if(tags.length===0){$tagsSelect.append('<option value="">No tags found</option>')}else{tags.forEach((tag)=>{const tagValue=String(tag.name||tag.id||'');if(!tagValue){return}
const isSelected=savedTags.includes(tagValue);$tagsSelect.append($('<option></option>').attr('value',tagValue).text(tagValue).prop('selected',isSelected))})}
if(typeof $.fn.select2!=='undefined'){$tagsSelect.select2({tags:!0,tokenSeparators:[','],placeholder:'Select tags to apply on user registration',allowClear:!0,width:'100%',closeOnSelect:!1,scrollAfterSelect:!1})}},bindEvents:function(){$('.ghl-wizard-next').on('click',()=>this.nextStep());$('.ghl-wizard-prev').on('click',()=>this.prevStep());$('.ghl-wizard-finish').on('click',()=>this.finish());$('.ghl-tab-button').on('click',function(){const tab=$(this).data('tab');$('.ghl-tab-button').removeClass('active');$(this).addClass('active');$('.ghl-tab-content').removeClass('active');$('#'+tab+'-tab').addClass('active')});$(document).on('click','#ghl-wizard-change-connection',function(){const $trigger=$(this);const $content=$('#ghl-wizard-connection-options');$trigger.toggleClass('active');$content.slideToggle(300)})},nextStep:function(){if(this.currentStep===2&&!this.isConnected()){this.showError('Please connect to GoHighLevel first');return}
this.collectCurrentStepData();if(this.currentStep<this.totalSteps){this.currentStep++;this.showStep(this.currentStep)}},prevStep:function(){if(this.currentStep>1){this.currentStep--;this.showStep(this.currentStep)}},showStep:function(step){$('.ghl-wizard-panel').removeClass('active');$(`.ghl-wizard-panel[data-step="${step}"]`).addClass('active');this.updateStepIndicators();window.scrollTo({top:0,behavior:'smooth'});if(step===this.totalSteps){this.celebrate()}},updateStepIndicators:function(){$('.ghl-setup-step').each((index,el)=>{const stepNum=index+1;const $number=$(el).find('.ghl-step-number');if(stepNum<this.currentStep){$(el).addClass('completed').removeClass('active');if(!$number.data('ghl-checked')){$number.data('ghl-checked',!0).html('<span class="dashicons dashicons-yes-alt"></span>')}}else if(stepNum===this.currentStep){$(el).addClass('active').removeClass('completed');$number.data('ghl-checked',!1).html(stepNum)}else{$(el).removeClass('active completed');$number.data('ghl-checked',!1).html(stepNum)}})},collectCurrentStepData:function(){switch(this.currentStep){case 3:this.settings.enable_user_sync=$('#wizard_enable_user_sync').is(':checked');this.settings.user_register=$('#wizard_user_register').is(':checked');this.settings.user_register_tags=$('#wizard_user_register_tags').val()||[];break;case 4:this.settings.woocommerce=$('#wizard_woocommerce').is(':checked');this.settings.buddyboss=$('#wizard_buddyboss').is(':checked');this.settings.learndash=$('#wizard_learndash').is(':checked');break;case 5:this.settings.delete_contact_on_user_delete=$('#wizard_delete_contact_on_user_delete').is(':checked');this.settings.enable_sync_logging=$('#wizard_enable_sync_logging').is(':checked');this.settings.enable_telemetry_reporting=$('#wizard_enable_telemetry_reporting').is(':checked');break}},isConnected:function(){return syncly_setup_wizard_js_data.isConnected==='1'},finish:function(){const button=$('.ghl-wizard-finish');const originalText=button.html();button.prop('disabled',!0).html('<span class="dashicons dashicons-update spin"></span> Saving...');$.ajax({url:syncly_setup_wizard_js_data.ajaxUrl,method:'POST',data:{action:'syncly_save_wizard_settings',nonce:syncly_setup_wizard_js_data.nonce,settings:this.settings},success:(response)=>{if(response.success){this.celebrate();setTimeout(()=>{window.location.href=syncly_setup_wizard_js_data.dashboardUrl},1100)}else{this.showError(response.data.message||'Failed to save settings');button.prop('disabled',!1).html(originalText)}},error:()=>{this.showError('Failed to save settings. Please try again.');button.prop('disabled',!1).html(originalText)}})},showError:function(message){if(typeof Swal!=='undefined'){Swal.fire({icon:'error',title:'Oops...',text:message,confirmButtonColor:'#4F46E5'})}else{alert(message)}},celebrate:function(){const canvas=document.getElementById('ghl-confetti-canvas');if(!canvas||canvas.__ghlRunning){return}
canvas.__ghlRunning=!0;const ctx=canvas.getContext('2d');const dpr=window.devicePixelRatio||1;const resize=()=>{canvas.width=window.innerWidth*dpr;canvas.height=window.innerHeight*dpr;canvas.style.width=window.innerWidth+'px';canvas.style.height=window.innerHeight+'px';ctx.setTransform(dpr,0,0,dpr,0,0)};resize();canvas.style.display='block';const colors=['#635bff','#10b981','#f59e0b','#ef4444','#3b82f6','#ec4899'];const count=220;const particles=Array.from({length:count},(_,i)=>{const fromCorner=i%3!==0;const originX=fromCorner?(i%2===0?0:window.innerWidth):Math.random()*window.innerWidth;const originY=fromCorner?window.innerHeight*0.85:-20-Math.random()*window.innerHeight*0.3;return{x:originX,y:originY,size:6+Math.random()*6,color:colors[Math.floor(Math.random()*colors.length)],speedY:fromCorner?-(6+Math.random()*6):2+Math.random()*3,speedX:fromCorner?(originX===0?1:-1)*(2+Math.random()*4):(Math.random()-0.5)*2,gravity:fromCorner?0.25:0,rotation:Math.random()*360,rotationSpeed:(Math.random()-0.5)*10}});const duration=3200;const start=performance.now();function frame(now){const elapsed=now-start;ctx.clearRect(0,0,window.innerWidth,window.innerHeight);particles.forEach((p)=>{p.speedY+=p.gravity;p.x+=p.speedX;p.y+=p.speedY;p.rotation+=p.rotationSpeed;ctx.save();ctx.translate(p.x,p.y);ctx.rotate((p.rotation*Math.PI)/180);ctx.fillStyle=p.color;ctx.fillRect(-p.size/2,-p.size/4,p.size,p.size/2);ctx.restore()});if(elapsed<duration){requestAnimationFrame(frame)}else{ctx.clearRect(0,0,window.innerWidth,window.innerHeight);canvas.style.display='none';canvas.__ghlRunning=!1}}
requestAnimationFrame(frame)}};$(document).ready(function(){GHLWizard.init()});const style=document.createElement('style');style.textContent=`
        @keyframes spin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }
        .spin { animation: spin 1s linear infinite; }
    `;document.head.appendChild(style)})(jQuery)